package dev.veltraph.client.core;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class RootOwnDisableReceiptTest {
 static class P extends AbstractModule {
  final ModuleManager root;ModuleManager.OwnDisableReceipt stopped;int disables,hooks;Runnable disable=()->{},post=()->{};
  P(ModuleManager root,String id){super(id,id,ModuleCategory.MISC);this.root=root;}
  public void onDisable(){disables++;assertFalse(isEnabled());assertEquals(MacroState.RUNNING,state());assertTrue(root.currentOwnDisableReceipt(this).isEmpty());disable.run();}
  protected void postDisableNormalReturned(ModuleManager.OwnDisableReceipt receipt){hooks++;stopped=receipt;assertEquals(MacroState.STOPPED,state());assertTrue(receipt.returnedCurrent());assertNotNull(receipt.stoppedSnapshot());assertFalse(receipt.current());post.run();}
 }
 @Test void realDisableReturnMintsOnlyAfterActualStoppedAndConfirmsAfterReadOnlyHook(){var root=new ModuleManager();var p=new P(root,"p");root.register(p);p.setEnabled(true);p.setEnabled(false);assertEquals(1,p.disables);assertEquals(1,p.hooks);assertNotNull(p.stopped);assertTrue(p.stopped.current());assertFalse(p.stopped.returnedCurrent());assertTrue(root.currentOwnDisableReceipt(p).isEmpty());}
 @Test void publicOnDisableDoesNotInvokeActualPostReturnOrMintReceipt(){var root=new ModuleManager();var p=new P(root,"p"){public void onDisable(){disables++;assertTrue(root.currentOwnDisableReceipt(this).isEmpty());}};root.register(p);p.onDisable();assertEquals(1,p.disables);assertEquals(0,p.hooks);assertNull(p.stopped);}
 @Test void actualDisableExceptionPreservesOldStateAndNeverCallsPostReturn(){var root=new ModuleManager();var p=new P(root,"p");root.register(p);p.setEnabled(true);p.disable=()->{throw new IllegalStateException("disable failed");};assertThrows(IllegalStateException.class,()->p.setEnabled(false));assertFalse(p.isEnabled());assertEquals(MacroState.RUNNING,p.state());assertEquals(0,p.hooks);assertNull(p.stopped);assertTrue(root.currentOwnDisableReceipt(p).isEmpty());}
 @Test void sourceOtherRosterChangedInsideDisableHasNoQualifiedPostReturn(){var root=new ModuleManager();var p=new P(root,"p");var q=new P(root,"q");root.register(p);root.register(q);p.setEnabled(true);p.disable=()->q.setEnabled(true);p.setEnabled(false);assertNull(p.stopped);assertEquals(0,p.hooks);assertTrue(q.isEnabled());}
 @Test void registrationAndSupplierChangeInsideDisableDenyOnlyReceipt(){var root=new ModuleManager();var p=new P(root,"p");root.register(p);p.setEnabled(true);p.disable=()->root.leasedInputOwner(()->null);p.setEnabled(false);assertNull(p.stopped);assertEquals(MacroState.STOPPED,p.state());}
 @Test void reentrantEnableInsidePostReturnRevokesDisableAndEnableProof(){var root=new ModuleManager();var p=new P(root,"p");root.register(p);p.setEnabled(true);p.post=()->p.setEnabled(true);p.setEnabled(false);assertNotNull(p.stopped);assertFalse(p.stopped.current());assertTrue(p.isEnabled());assertTrue(root.currentOwnDisableReceipt(p).isEmpty());}
 @Test void postReturnExceptionMakesReceiptUnknownWithoutUndoingStoppedState(){var root=new ModuleManager();var p=new P(root,"p");root.register(p);p.setEnabled(true);p.post=()->{throw new IllegalStateException("post hook failed");};assertThrows(IllegalStateException.class,()->p.setEnabled(false));assertNotNull(p.stopped);assertFalse(p.stopped.current());assertFalse(p.isEnabled());assertEquals(MacroState.STOPPED,p.state());}
 @Test void exactStoppedSnapshotCanMatchNextActualEnableAndRejectExtraCycle(){var root=new ModuleManager();var p=new P(root,"p"){ModuleManager.OwnEnableReceipt entry;public void onEnable(){entry=root.currentOwnEnableReceipt(this).orElse(null);}};root.register(p);p.setEnabled(true);p.setEnabled(false);var stopped=p.stopped.stoppedSnapshot();assertNotNull(stopped);p.setEnabled(true);assertTrue(root.ownEnableMatches(p.entry,stopped,p));p.setEnabled(false);p.setEnabled(true);assertFalse(root.ownEnableMatches(p.entry,stopped,p));}
}
